// The registry is the security boundary. The model may only ever choose names
// that appear here; anything else is rejected before a query is built, so a
// prompt injection cannot widen what is queryable.
const METRICS = {
  clicks:      { column: 'clicks',      agg: 'sum', label: 'Clicks',      description: 'Number of clicks.' },
  impressions: { column: 'impressions', agg: 'sum', label: 'Impressions', description: 'Times a result was shown.' },
  position:    { column: 'position',    agg: 'avg', label: 'Average position', description: 'Mean ranking position, lower is better.' },
  ctr:         { column: null,          agg: 'derived', label: 'Click-through rate', description: 'clicks divided by impressions, computed after aggregation.' }
};

const DIMENSIONS = {
  query:      { column: 'query',      label: 'Search query' },
  page:       { column: 'page',       label: 'Landing page' },
  country:    { column: 'country',    label: 'Country, ISO-3 lower case.' },
  device:     { column: 'device',     label: 'Device: mobile, desktop or tablet.' },
  event_date: { column: 'event_date', label: 'Date, YYYY-MM-DD.' }
};

const req = $json;
const metricLines = Object.keys(METRICS).map(function (k) { return '- ' + k + ': ' + METRICS[k].description; }).join('\n');
const dimensionLines = Object.keys(DIMENSIONS).map(function (k) { return '- ' + k + ': ' + DIMENSIONS[k].label; }).join('\n');

return {
  json: {
    question: String(req.question || '').trim(),
    property: String(req.property || 'https://example-store.test/'),
    source_workflow: req.source_workflow || 'unknown',
    today: new Date().toISOString().slice(0, 10),
    date_range_default: 'the whole of August 2026, which is the range the demo dataset covers',
    metric_registry: metricLines,
    dimension_registry: dimensionLines,
    metrics_available: Object.keys(METRICS),
    dimensions_available: Object.keys(DIMENSIONS),
    registry: { metrics: METRICS, dimensions: DIMENSIONS },
    started_at_ms: Date.now()
  }
};

// The deterministic compiler. Nothing the model said is trusted: every metric,
// dimension, filter field and operator must appear in the registry, and the SQL
// is assembled here from registry values with the user's values bound as
// parameters. The model's text never reaches a query string.
const ctx = $('Load Metric Registry').first().json;
const raw = ($json && $json.json) ? $json.json : $json;
const REG = ctx.registry;

function repairJson(text) {
  try { return JSON.parse(text); } catch (e) { /* continue */ }
  const stack = [];
  let inStr = false, esc = false, lastEnd = -1;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) { if (esc) { esc = false; } else if (c === '\\') { esc = true; } else if (c === '"') { inStr = false; } continue; }
    if (c === '"') { inStr = true; continue; }
    if (c === '{' || c === '[') { stack.push(c); }
    else if (c === '}' || c === ']') { stack.pop(); if (stack.length === 0) { lastEnd = i; } }
  }
  if (lastEnd > 0) { try { return JSON.parse(text.slice(0, lastEnd + 1)); } catch (e) { /* continue */ } }
  let patched = text;
  if (inStr) { patched += '"'; }
  patched = patched.replace(/,\s*"[^"]*"\s*:?\s*[^,{}\[\]]*$/, '').replace(/,\s*$/, '');
  for (let i = stack.length - 1; i >= 0; i--) { patched += (stack[i] === '{' ? '}' : ']'); }
  try { return JSON.parse(patched); } catch (e) { return null; }
}

const rejections = [];
let spec = null;
if (raw && raw.ok && raw.output) {
  const cleaned = String(raw.output).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  spec = repairJson(cleaned);
  if (!spec) { rejections.push('the planner response could not be parsed as JSON'); }
} else {
  rejections.push('the planner call failed: ' + ((raw && raw.error) ? raw.error : 'no output'));
}
if (!spec) { spec = {}; }

// A planner that could not answer says so explicitly. Honour that.
if (spec.unsupported_reason) { rejections.push('planner reported the question is unsupported: ' + spec.unsupported_reason); }

// ---- Whitelist enforcement ---------------------------------------------
const metrics = (Array.isArray(spec.metrics) ? spec.metrics : []).filter(function (m) {
  if (REG.metrics[m]) { return true; }
  rejections.push('metric "' + String(m).slice(0, 40) + '" is not in the registry');
  return false;
});
const dimensions = (Array.isArray(spec.dimensions) ? spec.dimensions : []).filter(function (d) {
  if (REG.dimensions[d]) { return true; }
  rejections.push('dimension "' + String(d).slice(0, 40) + '" is not in the registry');
  return false;
});

const ALLOWED_OPS = ['eq', 'neq', 'contains', 'gt', 'gte', 'lt', 'lte'];
const filters = (Array.isArray(spec.filters) ? spec.filters : []).filter(function (f) {
  if (!f || !REG.dimensions[f.field]) { rejections.push('filter field "' + String(f && f.field).slice(0, 40) + '" is not a registered dimension'); return false; }
  if (ALLOWED_OPS.indexOf(f.op) === -1) { rejections.push('filter operator "' + String(f && f.op).slice(0, 20) + '" is not allowed'); return false; }
  if (f.value === null || f.value === undefined) { rejections.push('filter on "' + f.field + '" has no value'); return false; }
  return true;
});

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const dateFrom = ISO.test(String(spec.date_from || '')) ? spec.date_from : '2026-08-01';
const dateTo = ISO.test(String(spec.date_to || '')) ? spec.date_to : '2026-08-31';
if (!ISO.test(String(spec.date_from || ''))) { rejections.push('date_from was missing or malformed, defaulted to 2026-08-01'); }
if (!ISO.test(String(spec.date_to || ''))) { rejections.push('date_to was missing or malformed, defaulted to 2026-08-31'); }

let limit = Number(spec.limit);
if (!isFinite(limit) || limit < 1) { limit = 10; }
limit = Math.min(1000, Math.floor(limit));

let orderField = null;
let orderDir = 'desc';
if (spec.order_by && spec.order_by.field) {
  if (REG.metrics[spec.order_by.field] || REG.dimensions[spec.order_by.field]) {
    orderField = spec.order_by.field;
    orderDir = String(spec.order_by.direction || 'desc').toLowerCase() === 'asc' ? 'asc' : 'desc';
  } else {
    rejections.push('order_by field "' + String(spec.order_by.field).slice(0, 40) + '" is not registered');
  }
}
if (!orderField && metrics.length) { orderField = metrics[0]; }

const fatal = metrics.length === 0;

// ---- Compile the equivalent parameterised SQL ---------------------------
// This is emitted for transparency and audit. Column names come from the
// registry, never from the model; user values are bound parameters, never
// interpolated. The demo executes against an n8n Data Table, but this is the
// exact statement a Postgres adapter would prepare.
const selectParts = dimensions.map(function (d) { return REG.dimensions[d].column; });
metrics.forEach(function (m) {
  const def = REG.metrics[m];
  if (def.agg === 'sum') { selectParts.push('SUM(' + def.column + ') AS ' + m); }
  else if (def.agg === 'avg') { selectParts.push('ROUND(AVG(' + def.column + ')::numeric, 2) AS ' + m); }
  else if (m === 'ctr') { selectParts.push('CASE WHEN SUM(impressions) = 0 THEN 0 ELSE ROUND(SUM(clicks)::numeric / SUM(impressions), 4) END AS ctr'); }
});
const params = [ctx.property, dateFrom, dateTo];
const whereParts = ['property = $1', 'event_date >= $2', 'event_date <= $3'];
filters.forEach(function (f) {
  const col = REG.dimensions[f.field].column;
  const opSql = { eq: '=', neq: '<>', gt: '>', gte: '>=', lt: '<', lte: '<=', contains: 'ILIKE' }[f.op];
  params.push(f.op === 'contains' ? ('%' + String(f.value) + '%') : f.value);
  whereParts.push(col + ' ' + opSql + ' $' + params.length);
});
const sql = 'SELECT ' + (selectParts.join(', ') || '1') +
  ' FROM analytics_events WHERE ' + whereParts.join(' AND ') +
  (dimensions.length ? (' GROUP BY ' + dimensions.map(function (d) { return REG.dimensions[d].column; }).join(', ')) : '') +
  (orderField ? (' ORDER BY ' + orderField + ' ' + orderDir.toUpperCase()) : '') +
  ' LIMIT ' + limit;

return {
  json: {
    question: ctx.question,
    property: ctx.property,
    today: ctx.today,
    started_at_ms: ctx.started_at_ms,
    source_workflow: ctx.source_workflow,
    valid: !fatal,
    intent: spec.intent || 'unknown',
    metrics: metrics,
    dimensions: dimensions,
    filters: filters,
    date_from: dateFrom,
    date_to: dateTo,
    order_by: orderField ? { field: orderField, direction: orderDir } : null,
    limit: limit,
    assumptions: Array.isArray(spec.assumptions) ? spec.assumptions : [],
    rejections: rejections,
    unsupported_reason: fatal
      ? (spec.unsupported_reason || 'No registered metric could be resolved from the question, so no query was run.')
      : null,
    compiled_sql: sql,
    sql_parameters: params,
    spec_json: JSON.stringify({ intent: spec.intent, metrics: metrics, dimensions: dimensions, filters: filters, date_from: dateFrom, date_to: dateTo, order_by: orderField ? { field: orderField, direction: orderDir } : null, limit: limit }),
    router: { provider: raw ? raw.selected_provider : null, model: raw ? raw.selected_model : null, latency_ms: raw ? raw.latency_ms : null, estimated_cost_usd: raw ? raw.estimated_cost_usd : null }
  }
};

// Applies the validated spec to the rows: filter, group, aggregate, order, limit.
// This is the in-memory equivalent of the compiled SQL, so the demo needs no
// database while the security property (registry-bound columns only) is identical.
const plan = $('Validate and Compile Query Spec').first().json;
const REG = $('Load Metric Registry').first().json.registry;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.event_date; });

function passes(row) {
  return plan.filters.every(function (f) {
    const col = REG.dimensions[f.field].column;
    const v = row[col];
    const target = f.value;
    if (f.op === 'eq') { return String(v).toLowerCase() === String(target).toLowerCase(); }
    if (f.op === 'neq') { return String(v).toLowerCase() !== String(target).toLowerCase(); }
    if (f.op === 'contains') { return String(v).toLowerCase().indexOf(String(target).toLowerCase()) !== -1; }
    const a = Number(v); const b = Number(target);
    if (!isFinite(a) || !isFinite(b)) { return false; }
    if (f.op === 'gt') { return a > b; }
    if (f.op === 'gte') { return a >= b; }
    if (f.op === 'lt') { return a < b; }
    if (f.op === 'lte') { return a <= b; }
    return false;
  });
}

const filtered = rows.filter(passes);

const groups = {};
filtered.forEach(function (row) {
  const key = plan.dimensions.map(function (d) { return String(row[REG.dimensions[d].column]); }).join('\u0001') || '__all__';
  if (!groups[key]) {
    groups[key] = { _clicks: 0, _impressions: 0, _positionSum: 0, _n: 0 };
    plan.dimensions.forEach(function (d) { groups[key][d] = row[REG.dimensions[d].column]; });
  }
  const g = groups[key];
  g._clicks += Number(row.clicks || 0);
  g._impressions += Number(row.impressions || 0);
  g._positionSum += Number(row.position || 0);
  g._n += 1;
});

let out = Object.keys(groups).map(function (k) {
  const g = groups[k];
  const rec = {};
  plan.dimensions.forEach(function (d) { rec[d] = g[d]; });
  plan.metrics.forEach(function (m) {
    if (m === 'clicks') { rec.clicks = g._clicks; }
    else if (m === 'impressions') { rec.impressions = g._impressions; }
    else if (m === 'position') { rec.position = g._n ? Math.round((g._positionSum / g._n) * 100) / 100 : null; }
    else if (m === 'ctr') { rec.ctr = g._impressions ? Math.round((g._clicks / g._impressions) * 10000) / 10000 : 0; }
  });
  rec._rows_aggregated = g._n;
  return rec;
});

if (plan.order_by) {
  const f = plan.order_by.field;
  const dir = plan.order_by.direction === 'asc' ? 1 : -1;
  out.sort(function (a, b) {
    const av = a[f]; const bv = b[f];
    if (typeof av === 'number' && typeof bv === 'number') { return (av - bv) * dir; }
    return String(av).localeCompare(String(bv)) * dir;
  });
}
out = out.slice(0, plan.limit);

return [{
  json: {
    rows: out,
    row_count: out.length,
    source_rows_scanned: rows.length,
    source_rows_after_filters: filtered.length,
    result_rows_text: out.length
      ? out.map(function (r, i) { return (i + 1) + '. ' + JSON.stringify(r); }).join('\n')
      : '(no rows matched)',
    warehouse: 'n8n Data Table agentic_analytics_demo (synthetic demo data)'
  }
}];

const plan = $('Validate and Compile Query Spec').first().json;

function unwrap(n) {
  try { const v = $(n).first().json; return (v && v.json) ? v.json : v; } catch (e) { return null; }
}
const narration = unwrap('Narrate Answer (02 Router)');
const verification = unwrap('Verify Answer (09)');
const plannerMeta = unwrap('Get Query Planner Prompt (08)');

let exec = null;
try { exec = $('Execute Query Plan').first().json; } catch (e) { exec = null; }

const unsupported = $input.all().some(function (i) { return i.json && i.json.unsupported; });

const costs = [];
if (plan.router && plan.router.estimated_cost_usd) { costs.push(Number(plan.router.estimated_cost_usd)); }
if (narration && narration.estimated_cost_usd) { costs.push(Number(narration.estimated_cost_usd)); }

return [{
  json: {
    generated_at: new Date().toISOString(),
    n8n_execution_id: $execution.id,
    question: plan.question,
    status: unsupported ? 'unsupported' : (exec && exec.row_count === 0 ? 'no_data' : 'answered'),
    answer: unsupported ? null : (narration && narration.ok ? String(narration.output || '') : null),
    unsupported_reason: plan.unsupported_reason,
    query: {
      intent: plan.intent,
      metrics: plan.metrics,
      dimensions: plan.dimensions,
      filters: plan.filters,
      date_from: plan.date_from,
      date_to: plan.date_to,
      order_by: plan.order_by,
      limit: plan.limit,
      assumptions: plan.assumptions,
      compiled_sql: plan.compiled_sql,
      sql_parameters: plan.sql_parameters,
      rejected_by_registry: plan.rejections
    },
    data: exec ? {
      rows: exec.rows, row_count: exec.row_count,
      source_rows_scanned: exec.source_rows_scanned,
      source_rows_after_filters: exec.source_rows_after_filters,
      warehouse: exec.warehouse
    } : null,
    verification: verification ? {
      verified: verification.verified, score: verification.score,
      issues: verification.issues, requires_human_review: verification.requires_human_review
    } : null,
    prompts: { planner: plannerMeta ? { version: plannerMeta.version, sha: plannerMeta.sha, degraded: plannerMeta.degraded } : null },
    models: {
      planner: plan.router,
      narrator: narration ? { provider: narration.selected_provider, model: narration.selected_model, latency_ms: narration.latency_ms, estimated_cost_usd: narration.estimated_cost_usd } : null
    },
    estimated_cost_usd_total: Math.round(costs.reduce(function (a, b) { return a + b; }, 0) * 1000000) / 1000000,
    latency_ms: plan.started_at_ms ? (Date.now() - Number(plan.started_at_ms)) : null
  }
}];

// raw.githubusercontent serves text/plain, so the body may arrive as a string.
const item = $input.first().json;
let doc = item;
if (typeof item === 'string') { doc = JSON.parse(item); }
else if (typeof item.data === 'string') { doc = JSON.parse(item.data); }
else if (typeof item.body === 'string') { doc = JSON.parse(item.body); }
else if (item.body) { doc = item.body; }

if (!doc || !Array.isArray(doc.rows)) {
  throw new Error('dataset did not contain a rows array; observed keys: ' + Object.keys(doc || {}).join(', '));
}
return doc.rows.map(function (r) { return { json: r }; });
